class Solution:
    def maxRotateFunction(self, nums: List[int]) -> int:
        n = len(nums)
        total_sum = sum(nums)
        cur_f = sum(i * x for i, x in enumerate(nums))
        max_f = cur_f
        for k in range(1, n):
            cur_f = cur_f + total_sum - n * nums[n - k]
            max_f = max(max_f, cur_f)
        return max_f

class Solution {
public:
    int maxRotateFunction(vector<int>& nums) {
        long long n = nums.size();
        long long totalSum = 0;
        long long curF = 0;
        for (long long i = 0; i < n; i++) {
            totalSum += nums[i];
            curF += i * nums[i];
        }
        long long maxF = curF;
        for (int k = 1; k < n; k++) {
            curF = curF + totalSum - n * nums[n - k];
            maxF = max(maxF, curF);
        }
        return (int)maxF;
    }
};

class Solution {
    public int maxRotateFunction(int[] nums) {
        int n = nums.length;
        long totalSum = 0;
        long curF = 0;
        for (int i = 0; i < n; i++) {
            totalSum += nums[i];
            curF += (long) i * nums[i];
        }
        long maxF = curF;
        for (int k = 1; k < n; k++) {
            curF = curF + totalSum - (long) n * nums[n - k];
            maxF = Math.max(maxF, curF);
        }
        return (int) maxF;
    }
}

